	(1, 'vision', 'Vision Statement', 'मंत्रिमंडल सचिवालय भारत सरकार (कार्यकरण) नियम, 1961 तथा भारत सरकार (कार्य-आबंटन) नियम, 1961 के प्रशासन के लिए उत्तरदायी है, जिससे सरकार के मंत्रालयों/विभागों में निर्बाध कार्य संचालन में आसानी होती है ।', 'text', 1, 1, NULL, NULL, NULL, '2026-04-30 01:04:38', '2026-10-12 08:11:39'),
	(2, 'functions', 'Functions', 'मंत्रिमंडल सचिवालय सीधे प्रधानमंत्री के अधीन कार्य करता है। सचिवालय का प्रशासनिक प्रमुख मंत्रिमंडल सचिव होता है जो सिविल सेवा बोर्ड का पदेन अध्यक्ष भी होता है। भारत सरकार (कार्य आबंटन) नियम, 1961 के तहत मंत्रिमंडल सचिवालय को आवंटित कार्य में (i) मंत्रिमंडल और मंत्रिमंडल समितियों को सचिवीय सहायता; और (ii) कार्य के नियम शामिल हैं। \r\n<br><br>\r\nमंत्रिमंडल सचिवालय भारत सरकार (कार्यकरण) नियम, 1961 और भारत सरकार (कार्य आबंटन) नियम, 1961 के प्रशासन के लिए उत्तरदायी है, जो केन्द्र सरकार के मंत्रालयों/विभागों में निर्बाध कार्य संचालन में सुविधा प्रदान करता है। यह सचिवालय मंत्रिमंडल और इसकी समितियों को सचिवीय सहायता प्रदान करता है और अंतर-मंत्रालयी समन्वय सुनिश्चित करके, मंत्रालयों/विभागों के बीच मतभेदों को दूर करके और सचिवों की स्थायी/तदर्थ समितियों के माध्यम से आम सहमति बनाकर सरकार में निर्णय लेने में भी सहायता करता है। इस तंत्र के माध्यम से, नई नीतिगत पहलों को भी बढ़ावा दिया जाता है। देश में बड़े संकट की स्थितियों का प्रबंधन करना और ऐसी स्थिति में विभिन्न मंत्रालयों/विभागों की गतिविधियों का समन्वय करना भी मंत्रिमंडल सचिवालय के कार्यों में से एक है।\r\n<br><br>\r\n\r\n<strong>सरकारी कामकाज का आवंटन और निपटान</strong>\r\n<ul>\r\n 	<li>भारत सरकार (कार्य आबंटन) नियम, 1961 (एओबी नियम) और भारत सरकार (कार्यकरण) नियम, 1961 (टीओबी नियम) भारत के संविधान के अनुच्छेद 77 (3) के तहत तैयार किए गए हैं। एओबी नियमों की प्रथम अनुसूची मंत्रालयों, विभागों, कार्यालयों और सचिवालयों को विनिर्दिष्ट करती है जबकि द्वितीय अनुसूची भारत सरकार के विभिन्न मंत्रालयों/विभागों को आवंटित कार्यों को सूचीबद्ध करती है।</li>\r\n\r\n 	<li>कार्यकरण नियम, भारत सरकार में कार्य के निपटान तथा निर्णय लेने की प्रक्रिया का निर्धारण करते हैं। भारत सरकार में कार्य का निपटान साधारणत:, कार्यकरण नियमों में निर्धारित अपेक्षित विभागीय परामर्शों के अध्‍यधीन, मंत्रालयों/विभागों के भीतर विभिन्‍न स्‍तरों पर प्रभारी मंत्री द्वारा या उनके सामान्‍य अथवा विशेष निर्देशों के अंतर्गत किया जाता है । इसके अतिरिक्‍त, कार्यकरण नियम उन मामलों को विनिर्दिष्‍ट करते हैं जिनके लिए प्रधानमंत्री, मंत्रिमंडल और इसकी समितियों तथा राष्‍ट्रपति का अनुमोदन अपेक्षित होता है। वे मामले जिनके लिए मंत्रिमंडल का अनुमोदन अपेक्षित है, कार्यकरण नियमों की द्वितीय अनुसूची में दर्शाए गए हैं तथा वे मामले जिन पर मंत्रिमंडल की समितियों का अनुमोदन अपेक्षित है, कार्यकरण नियमों की प्रथम अनुसूची में दर्शाए गए हैं। ऐसे मामलों को कार्यकरण नियमों की तृतीय अनुसूची में सूचीबद्ध किया गया है जिन्‍हें प्रधानमंत्री तथा राष्‍ट्रपति को प्रस्‍तुत करना अपेक्षित है। तदनुसार, जबकि सरकारी कार्यों के एक महत्‍वपूर्ण भाग का निपटान विभागीय स्‍तर पर कर लिया जाता है, कुछ मामलों या मामलों के वर्ग, जो राष्‍ट्रीय परिप्रेक्ष्‍य में महत्‍वपूर्ण हैं, के लिए मंत्रिमंडल अथवा मंत्रिमंडल की किसी एक समिति का अनुमोदन अपेक्षित होता है।</li>\r\n</ul>\r\n<br>\r\n<strong>मंत्रिमंडल समितियों को सहायता</strong>\r\n<br>\r\nमंत्रिमंडल सचिवालय द्वारा मंत्रिमंडल तथा मंत्रिमंडल समितियों को दी जाने वाली सचिवालयी सहायता में निम्नलिखित शामिल हैं:\r\n<ul>\r\n 	<li>प्रधानमंत्री के आदेश पर मंत्रिमंडल और इसकी समितियों की बैठकें बुलाना।</li>\r\n 	<li>कार्यसूची तैयार करना तथा कार्यसूची में शामिल मामलों से संबंधित कागजात परिचालित करना।</li>\r\n 	<li>विचार-विमर्शों का रिकॉर्ड तैयार करना।</li>\r\n 	<li>प्रधानमंत्री का अनुमोदन प्राप्त करने के पश्चात, विचार-विमर्शों के रिकॉर्ड को परिचालित करना।</li>\r\n 	<li>मंत्रिमंडल और इसकी समितियों द्वारा लिए गए निर्णयों के कार्यान्वयन की निगरानी करना।</li>\r\n</ul>\r\nमंत्रिमंडल सचिवालय, मंत्रिमंडल की बैठकों के कागजात का अभिरक्षक है।\r\n<br><br>\r\n<strong>अंतरमंत्रालयी समन्वय को बढ़ावा देना</strong>\r\n<br>\r\nअंतरमंत्रालयी मामलों में, निम्नलिखित के लिए समन्वय की आवश्यकता होती है :\r\n<br>\r\n<ul>\r\n 	<li>कठिनाइयां दूर करना।</li>\r\n 	<li>मतभेद दूर करना।</li>\r\n 	<li>विलम्ब कम करना।</li>\r\n 	<li>प्रशासनिक कार्रवाई में समन्वय।</li>\r\n 	<li>नीतियों का समन्वय।</li>\r\n</ul>\r\n<br>\r\nजबकि प्रत्येक मंत्रालय सरकारी नीतियों, योजनाओं तथा कार्यक्रमों के शीघ्र कार्यान्वयन के लिए स्वयं ही कार्रवाई करने के लिए उत्तरदायी है, फिर भी जहां अंतरमंत्रालयी सहयोग अपेक्षित होता है, वहां वे प्रायः मंत्रिमंडल सचिवालय की सहायता लेते हैं। अंतरमंत्रालयी समस्‍याओं का समाधान सचिवों की समितियों (सीओएस) की बैठकों में निकाला जाता है। सरकार के विभिन्न सचिवों से प्राप्त विशेष मामलों और प्रस्तावों पर विचार विमर्श करने के लिए समितियों का गठन किया जाता है और मंत्रिमंडल सचिव की अध्यक्षता में इनकी बैठकें की जाती हैं। ये समितियां अड़चनों को दूर करने अथवा परस्पर सहयोगी अंतरमंत्रालयी कार्रवाई सुनिश्चित करने में सफल हुई हैं।\r\n<br><br>\r\nसचिवों की समितियों में विचार-विमर्श संबंधित मूल विभाग द्वारा तैयार किए गए दस्तावेज के आधार पर होता है और यदि कोई ऐसा विभाग है जिसका संबंधित विषय पर दृष्टिकोण भिन्न है तो पूरक नोट प्रस्तुत किया जाता है। सचिवों की समिति के निर्णय अथवा सिफारिशें एकमत से होती हैं। इन कार्यवाहियों को विभागों में परिचालित भी किया जाता है और विभाग उन पर अनुवर्ती कार्रवाई करते हैं। यह सचिवालय कुछ अन्य महत्वपूर्ण कार्य भी करता है, जैसे :\r\n<br>\r\n<ul>\r\n 	<li>निगरानी।</li>\r\n 	<li>समन्वय।</li>\r\n 	<li>नई नीतिगत पहलों को प्रोत्साहित करना।</li>\r\n</ul>\r\n<br>\r\nमंत्रिमंडल सचिवालय को विभागों द्वारा अंतर-मंत्रालयी समन्वय को बढ़ावा देने के लिए एक उपयोगी तंत्र के रूप में देखा जाता है क्योंकि मंत्रिमंडल सचिव सिविल सेवाओं के प्रमुख भी होते हैं। मंत्रालयों/विभागों द्वारा मासिक अर्द्ध-शासकीय पत्रों की प्रणाली के माध्यम से मंत्रिमंडल सचिव को निम्नलिखित के बारे में अवगत कराया जाता है:\r\n<br>\r\n<ul>\r\n 	<li>दीर्घकालिक अंतर-मंत्रालयी परामर्शों के कारण लंबित नीतिगत और अन्य मामले;</li>\r\n 	<li>लंबे समय से लंबित प्रस्ताव/संदर्भ;</li>\r\n 	<li>किसी भी ऐसे मामले का विवरण जिसमें कार्य संचालन के नियमों से विचलन हुआ हो; और</li>\r\n 	<li>महत्वपूर्ण मामले / महत्वपूर्ण प्रगति (प्रगतियां)।</li>\r\n</ul>\r\n', 'text', 2, 1, NULL, NULL, NULL, '2026-04-30 01:04:38', '2026-10-12 08:16:24'),
	(6, 'origin', 'उद्गम', 'भारत सरकार में विभागीय प्रणाली अपनाए जाने से पूर्व, सारा सरकारी कार्य काउन्सिल में गवर्नर-जनरल- द्वारा निपटाया जाता था। यह काउन्सिल एक संयुक्त परामर्शदात्री बोर्ड के रूप में कार्य करती थी। सरकार के कार्य में जैसे-जैसे वृद्धि हुई और उसमें जटिलता आने लगी, विभिन्न विभागों के काम को काउन्सिल के सदस्यों में बांट दिया गया। केवल अधिक महत्वपूर्ण मामलों को गवर्नर-जनरल अथवा काउन्सिल द्वारा संयुक्त रूप से निपटाया जाता था।\r\n\r\n\r\n\r\nइस प्रक्रिया को लार्ड केनिंग के कार्यकाल के दौरान काउन्सिल अधिनियम, 1861 द्वारा वैध बनाया गया जिससे विभागीय प्रणाली की शुरूआत हुई और गवर्नर-जनरल की कार्यकारिणी परिषद की स्थापना हुई। वाइसराय का निजी सचिव इस कार्यकारी परिषद के सचिवालय का प्रमुख होता था, पर वह परिषद की बैठकों में सम्मिलित नहीं होता था। लार्ड विलिंग्‍डन ने इन बैठकों में अपने निजी सचिव को अपने साथ बैठाने की प्रथा आरंभ की। बाद में यह प्रथा जारी रही और नवम्बर, 1935 में वाइसराय के निजी सचिव को कार्यकारी परिषद के सचिव का अतिरिक्त पदनाम दिया गया। लेकिन बाद में इन पदों को अलग कर दिया गया, और वायसराय तथा गवर्नर-जनरल के निजी सचिव से अलग, कार्यकारी परिषद् में एक अलग सचिव नियुक्त किया गया।\r\n\r\n\r\nसितम्बर 1946 में अंतरिम सरकार के गठन से इस कार्यालय के नाम में परिवर्तन हुआ। 5 सितम्बर, 1946 को कार्यकारी परिषद के सचिवालय को मंत्रिमंडल सचिवालय और कार्यकारी परिषद के सचिव को मंत्रिमंडल सचिव के रूप में पदनामित किया गया। तथापि, ऐसा प्रतीत होता है कि स्वतंत्रता के बाद पहले की अपेक्षा मंत्रिमंडल सचिवालय के कार्यों में एक तरह से परिवर्तन हुआ है। अब इसका कार्य मंत्रियों और मंत्रालयों को कागजात परिचालित करने के सामान्‍य कार्य तक ही सीमित नहीं है, बल्कि यह मंत्रालयों के बीच प्रभावी समन्वय के लिए एक संगठन के रूप में विकसित हुआ है।\r\n\r\n', 'text', 6, 1, NULL, NULL, NULL, '2026-04-30 01:04:38', '2026-10-12 08:17:05'),
	(7, 'development', 'विकास', 'स्वतंत्रता के बाद, सन् 1949 में मंत्रिमंडल की एक आर्थिक समिति गठित की गई जिसका सचिवालय वित्त मंत्रालय में था। सन् 1950 में इसे मंत्रिमंडल सचिवालय में स्थानांतरित कर दिया गया और इसका नाम बदलकर आर्थिक स्कंध रखा गया और अंततः सन् 1955 में इस सचिवालय में इसका विलय कर दिया गया। सन् 1954 में मंत्रिमंडल सचिवालय के अंतर्गत संगठन एवं पद्धति प्रभाग की स्थापना की गई जिसे बाद में 1964 में गृह मंत्रालय को हस्तांतरित कर दिया गया। वर्तमान में, यह प्रशासनिक सुधार और लोक शिकायत विभाग के अंतर्गत है।<br>\r\n<br>\r\n1 अक्टूबर, 1947 को मंत्रिमंडल की रक्षा समिति का गठन किया गया था। मंत्रिमंडल की रक्षा समिति की सेवा में मंत्रिमंडल सचिव की सहायता के लिए, अक्टूबर, 1947 में ही मंत्रिमंडल सचिवालय में एक सैन्य विंग की स्थापना की गई थी। 1970 में, सीसीपीए ने मंत्रिमंडल की रक्षा समिति और मंत्रिमंडल की आंतरिक मामलों की समिति का स्थान लिया। सीसीपीए को सचिवालयीय सहायता मंत्रिमंडल सचिवालय के सिविल विंग द्वारा प्रदान की जाती थी और मंत्रिमंडल का सैन्य विंग रक्षा मंत्री की समितियों, चीफ्स ऑफ स्टाफ कमेटियों आदि के लिए सहायता प्रदान कर रहा था। चूंकि सैन्य विंग मंत्रिमंडल सचिवालय के भीतर किसी भी कार्य से जुड़ा नहीं था और कार्यात्मक रूप से रक्षा मंत्रालय से जुड़ा हुआ था, इसलिए सैन्य विंग को 1 जुलाई, 1991 से रक्षा मंत्रालय को हस्तांतरित कर दिया गया। \r\n<br><br>\r\nसांख्यिकी विभाग का गठन अप्रैल, 1961 में मंत्रिमंडल सचिवालय के तहत किया गया था और फरवरी, 1973 में योजना मंत्रालय को हस्तांतरित कर दिया गया था। अक्टूबर, 1999 में इसे एक मंत्रालय में परिवर्तित कर दिया गया था।\r\n<br><br>\r\nविशेष आर्थिक समन्वय विभाग की स्थापना जून, 1962 में मंत्रिमंडल सचिवालय के अंतर्गत की गई थी, जिसे नवंबर, 1962 में नवगठित आर्थिक और रक्षा समन्वय मंत्रालय के अंतर्गत समन्वय विभाग के रूप में रखा गया था। इसका काम 11 सितंबर, 1963 को वित्त मंत्रालय के तहत समन्वय विभाग को हस्तांतरित कर दिया गया और 14 जून, 1967 से इस विभाग का अस्तित्व समाप्त हो गया। इसका काम वित्त मंत्रालय के तहत आर्थिक कार्य  विभाग को स्थानांतरित कर दिया गया था।\r\n<br><br>\r\nसंयुक्त खुफिया समिति को सचिवीय सहायता प्रदान करने के लिए 1965 में एक खुफिया शाखा की स्थापना की गई थी।\r\n<br><br>\r\nलोक उद्यम ब्यूरो को जनवरी, 1966 से जून, 1966 तक की छोटी अवधि के लिए मंत्रिमंडल सचिवालय के तहत लाया गया था और इसे 6 जून, 1966 को वित्त मंत्रालय के तहत समन्वय विभाग में स्थानांतरित कर दिया गया। 14 जून, 1967 को इसे वित्त मंत्रालय के तहत व्यय विभाग में स्थानांतरित कर दिया गया। 25 सितंबर, 1985 को इसे उद्योग मंत्रालय के तहत एक अलग लोक उद्यम विभाग में बदल दिया गया था, जिसे 15 अक्टूबर, 1999 को भारी उद्योग और लोक उद्यम मंत्रालय के तहत रखा गया था। 6 जुलाई, 2021 से, यह विभाग वित्त मंत्रालय के अधीन है।\r\n<br><br>\r\n<strong>जून, 1970 में मंत्रिमंडल सचिवालय के तहत निम्नलिखित तीन विभाग बनाये गए थे:</strong>\r\n<br>\r\n<ul>\r\n 	<li>इलेक्ट्रॉनिकी विभाग</li>\r\n 	<li>वैज्ञानिक और औद्योगिक अनुसंधान विभाग, और</li>\r\n 	<li>कार्मिक विभाग</li>\r\n</ul>\r\n<br>\r\nजुलाई, 1970 में, राजस्व खुफिया महानिदेशालय-सह-प्रवर्तन निदेशालय की स्थापना मंत्रिमंडल सचिवालय के तहत मंत्रिमंडल कार्य विभाग के तहत की गई थी और बाद में इस निदेशालय को अगस्त, 1970 में कार्मिक विभाग में स्थानांतरित कर दिया गया था।\r\n<br><br>\r\nवैज्ञानिक और औद्योगिक अनुसंधान विभाग मई 1971 में स्वतंत्र विभाग बन गया और इसका नाम बदलकर विज्ञान और प्रौद्योगिकी विभाग कर दिया गया। 4 जनवरी, 1985 से, यह अपने प्रारंभिक नामकरण के साथ विज्ञान और प्रौद्योगिकी मंत्रालय के अधीन है।\r\n<br><br>\r\nइलेक्ट्रॉनिकी विभाग 1971 में स्वतंत्र विभाग बन गया और कार्मिक विभाग का नाम 07.02.1973 को कार्मिक एवं प्रशासनिक सुधार विभाग कर दिया गया। कार्मिक एवं प्रशासनिक सुधार विभाग को 1977 में मंत्रिमंडल सचिवालय से गृह मंत्रालय को स्थानांतरित कर दिया गया। वर्तमान में यह कार्मिक एवं प्रशिक्षण विभाग तथा प्रशासनिक सुधार एवं लोक शिकायत विभाग के रूप में विभाजन के साथ कार्मिक, लोक शिकायत एवं पेंशन मंत्रालय का एक हिस्सा है।\r\n<br><br>\r\nसमुद्री विकास विभाग की स्थापना जुलाई 1981 में मंत्रिमंडल सचिवालय के तहत की गई थी और फरवरी 1982 में यह स्वतंत्र विभाग बन गया। फरवरी 2006 में यह एक मंत्रालय बन गया और जुलाई 2006 से इसके कार्यों का संचालन पृथ्वी विज्ञान मंत्रालय द्वारा किया जा रहा है।\r\n<br><br>\r\n<strong>लोक शिकायत निदेशालय (डीपीजी)</strong>\r\n<br><br>\r\nलोक शिकायत निदेशालय की स्थापना मार्च, 1988 में मंत्रिमंडल सचिवालय में की गई थी। एमटीएनएल/बीएसएनएल, रेलवे, डाक, बीमा कंपनियां, सार्वजनिक क्षेत्र के बैंक आदि जैसे व्यापक सार्वजनिक संपर्क वाले चुनिंदा मंत्रालयों/विभागों/संगठनों के संबंध में लोक शिकायत निदेशालय में ऑनलाइन या डाक/ड्रॉप-बॉक्स के माध्यम से शिकायतें दर्ज की जा सकती हैं (सूची https://dpg.gov.in/Authpages/OgCovered.aspx पर उपलब्ध है)।\r\n<br>\r\nशिकायतों की प्रकृति और गंभीरता के आधार पर, निदेशालय या तो टिप्पणियाँ मांगता है या उन्हें उचित कार्रवाई के लिए संबंधित विभाग (विभागों) को हस्तांतरित करता है।\r\n<br><br>\r\n<strong>राष्ट्रीय प्राधिकरण रासायनिक हथियार समझौता (एनएसीडब्ल्यूसी)</strong>\r\n<br><br>\r\nरासायनिक हथियार समझौता (सीडब्ल्यूसी) के तहत भारत के दायित्वों को पूरा करने के लिए राष्ट्रीय प्राधिकरण रासायनिक हथियार समझौता की स्थापना की गई थी। सीडब्ल्यूसी रासायनिक हथियारों के विकास, उत्पादन, भंडारण और उपयोग के निषेध के संबंध में एक बहुपक्षीय अंतरराष्ट्रीय संधि है। यह समझौता 29 अप्रैल, 1997 को लागू हुआ। 31 मार्च, 2025 तक, 193 पक्षकार राज्यों (देशों) ने इस संधि का अनुसमर्थन किया है या स्वीकार कर लिया है। रासायनिक हथियार निषेध संगठन (ओपीसीडब्ल्यू) हेग, नीदरलैंड में स्थित है, जो इस समझौता के लिए कार्यान्वयन निकाय है। ओपीसीडब्ल्यू को रासायनिक हथियारों के वैश्विक उन्मूलन की दिशा में इसके प्रयासों को मान्यता देने के लिए 2013 में नोबेल शांति पुरस्कार से सम्मानित किया गया था।\r\n<br>\r\nराष्ट्रीय प्राधिकरण रासायनिक हथियार समझौता का गठन 5 मई, 1997 को मंत्रिमंडल सचिवालय द्वारा किया गया था। रासायनिक हथियार समझौता अधिनियम, 2000 (अधिनियम) 1 जुलाई, 2005 को अधिनियमित और लागू किया गया था। सीडब्ल्यूसी अधिनियम, 2000 के तहत 13 जून 2005 को प्राधिकरण की स्थापना की गई और इसे अधिसूचित किया गया था।\r\n<br>\r\nराष्ट्रीय प्राधिकरण का नेतृत्व अध्यक्ष द्वारा किया जाता है, जिसके पास भारत सरकार के सचिव के बराबर रैंक होगा और इसके विभिन्न कार्यों की देखभाल के लिए इसकी सहायता के लिए एक उपयुक्त तकनीकी सचिवालय होता है। प्राधिकरण के कार्यों की निगरानी करने और उपर्युक्त अधिनियम के प्रावधानों के अनुसार केंद्र सरकार की शक्तियों का प्रयोग करने और उनका निष्पादन करने के लिए, मंत्रिमंडल सचिव की अध्यक्षता में गृह सचिव, विदेश सचिव, सचिव, रक्षा मंत्रालय, सचिव, राजस्व विभाग, सचिव, रसायन और पेट्रोरसायन विभाग, सचिव, रक्षा अनुसंधान एवं विकास विभाग और सचिव, वाणिज्य विभाग के साथ एक उच्च स्तरीय संचालन समिति की स्थापना की गई है। \r\n<br>\r\nराष्ट्रीय प्राधिकरण सीडब्ल्यूसी अधिनियम के कार्यान्वयन, ओपीसीडब्ल्यू और समझौता के अन्य पक्षकार राज्यों (देशों) के साथ संपर्क, घोषणाओं को समय पर प्रस्तुत करने, ओपीसीडब्ल्यू निरीक्षणों का समन्वय करने आदि सहित भारत के संधि दायित्वों को पूरा करने के लिए उत्तरदायी है।\r\n<br><br>\r\n<strong>प्रत्यक्ष लाभ अंतरण (डीबीटी) मिशन</strong>\r\n<br>\r\nडीबीटी एक प्रमुख सुधार पहल है जिसमें आधार का उपयोग करके लक्षित लाभार्थियों को सीधे लाभ, नकद या वस्तु के रूप में, वितरित किया जाता है। यह वितरण प्रक्रियाओं में दक्षता और समावेश की परिकल्पना करता है जिससे सिस्टम में अधिक जवाबदेही और पारदर्शिता आती है।\r\n<br>\r\nडीबीटी मिशन को डीबीटी के कार्यान्वयन के लिए एक नोडल केंद्र के रूप में कार्य करने के लिए योजना आयोग में बनाया गया था। मिशन को 13 जुलाई को व्यय विभाग को हस्तांतरित कर दिया गया था और 14.09.2015 से मंत्रिमंडल सचिवालय में स्थानांतरित कर दिया गया था। \r\n<br><br>\r\n<strong>प्रमुख वैज्ञानिक सलाहकार का कार्यालय (पीएसए का कार्यालय)</strong>\r\n<br>\r\nभारत सरकार के प्रमुख वैज्ञानिक सलाहकार का कार्यालय (पीएसए का कार्यालय) की स्थापना नवंबर 1999 में निम्नलिखित के लिए की गई थी: \r\n<br>\r\n<ul>\r\n 	<li>बहु अनुप्रयोगों के लिए नवाचारों और सहायता पद्धतियों के सृजन हेतु नीतियां, कार्यनीतियां और मिशन तैयार करना,</li>\r\n 	<li>भारत सरकार के विभागों, संस्थाओं एवं उद्योग की सहभागिता से महत्वपूर्ण अवसंरचना, आर्थिक और सामाजिक क्षेत्रों में विज्ञान एवं प्रौद्योगिकी संबंधी कार्य सृजित करना।</li>\r\n</ul>\r\nप्रमुख वैज्ञानिक सलाहकार का कार्यालय  <strong>प्रधान मंत्री की विज्ञान, प्रौद्योगिकी और नवाचार संबंधी सलाहकार परिषद् (पीएम-एसटीआईएसी) </strong>को भी सेवा प्रदान करता है।\r\n<br>\r\nप्रमुख वैज्ञानिक सलाहकार के कार्यालय को अगस्त, 2018 में प्रशासनिक रूप से मंत्रिमंडल सचिवालय के नियंत्रण में कर दिया गया है। \r\n', 'text', 7, 1, NULL, NULL, NULL, '2026-04-30 01:04:38', '2026-10-12 08:21:48'),
