\\" stroke-width=\\"1.3\\" stroke-linecap=\\"round\\"\\r\\n                        stroke-linejoin=\\"round\\" />\\r\\n                </svg>\\r\\n                वेबसाइट देखें</a>\\r\\n        </div>\\r\\n\\r\\n        <div class=\\"link-card\\">\\r\\n            <span class=\\"link-text\\">डिजिलॉकर</span>\\r\\n            <a href=\\"https://www.digilocker.gov.in/\\" class=\\"visit-btn\\"><i class=\\"fas fa-external-link-alt\\"></i>\\r\\n                <svg width=\\"14\\" height=\\"14\\" viewBox=\\"0 0 14 14\\" fill=\\"none\\">\\r\\n                    <path d=\\"M6 2H2a1 1 0 00-1 1v9a1 1 0 001 1h9a1 1 0 001-1V8\\" stroke=\\"currentColor\\" stroke-width=\\"1.3\\"\\r\\n                        stroke-linecap=\\"round\\" />\\r\\n                    <path d=\\"M9 1h4v4M13 1L7 7\\" stroke=\\"currentColor\\" stroke-width=\\"1.3\\" stroke-linecap=\\"round\\"\\r\\n                        stroke-linejoin=\\"round\\" />\\r\\n                </svg>\\r\\n                वेबसाइट देखें</a>\\r\\n        </div>\\r\\n    </div>\\r\\n</div>","css":"* {\\r\\n    margin: 0;\\r\\n    padding: 0;\\r\\n    box-sizing: border-box;\\r\\n    font-family: \'Segoe UI\', Tahoma, Geneva, Verdana, sans-serif;\\r\\n}\\r\\n\\r\\nbody {\\r\\n    background-color: #fcfcfc; /* Light background as seen in image */\\r\\n    display: flex;\\r\\n    justify-content: center;\\r\\n    padding: 40px 20px;\\r\\n}\\r\\n\\r\\n.container {\\r\\n    width: 100%;\\r\\n    max-width: 900px;\\r\\n}\\r\\n\\r\\n/* Search Bar Styling */\\r\\n.search-container {\\r\\n    position: relative;\\r\\n    margin-bottom: 25px;\\r\\n}\\r\\n\\r\\n.search-icon {\\r\\n    position: absolute;\\r\\n    left: 15px;\\r\\n    top: 50%;\\r\\n    transform: translateY(-50%);\\r\\n    color: #4a7c92;\\r\\n    font-size: 18px;\\r\\n}\\r\\n\\r\\n.search-container input {\\r\\n    width: 100%;\\r\\n    padding: 12px 12px 12px 45px;\\r\\n    border: 1.5px solid #4a74d4; /* Blue border */\\r\\n    border-radius: 6px;\\r\\n    font-size: 16px;\\r\\n    color: #555;\\r\\n    outline: none;\\r\\n}\\r\\n\\r\\n/* Links Wrapper */\\r\\n.links-wrapper {\\r\\n    display: flex;\\r\\n    flex-direction: column;\\r\\n    gap: 12px; /* Spacing between cards */\\r\\n}\\r\\n\\r\\n/* Individual Link Card */\\r\\n.link-card {\\r\\n    background: #fff;\\r\\n    border: 1px solid #e0e0e0;\\r\\n    border-radius: 8px;\\r\\n    display: flex;\\r\\n    justify-content: space-between;\\r\\n    align-items: center;\\r\\n    padding: 10px 15px;\\r\\n    transition: box-shadow 0.3s ease;\\r\\n}\\r\\n\\r\\n.link-card:hover {\\r\\n    box-shadow: 0 2px 8px rgba(0,0,0,0.05);\\r\\n}\\r\\n\\r\\n.link-text {\\r\\n    font-size: 16px;\\r\\n    color: #333;\\r\\n    font-weight: 500;\\r\\n}\\r\\n\\r\\n/* Visit Website Button */\\r\\n.visit-btn {\\r\\n    background-color: #dbe4ff; /* Very light blue background */\\r\\n    color: #2c54c1; /* Strong blue text */\\r\\n    text-decoration: none;\\r\\n    font-size: 12px;\\r\\n    font-weight: bold;\\r\\n    padding: 10px 20px;\\r\\n    border-radius: 6px;\\r\\n    display: flex;\\r\\n    align-items: center;\\r\\n    gap: 8px;\\r\\n    transition: background 0.3s ease;\\r\\n}\\r\\n\\r\\n.visit-btn:hover {\\r\\n    background-color: #c9d6ff;\\r\\n}\\r\\n\\r\\n.visit-btn i {\\r\\n    font-size: 14px;\\r\\n}\\r\\n\\r\\n/* Responsive adjustment */\\r\\n@media (max-width: 600px) {\\r\\n    .link-card {\\r\\n        flex-direction: column;\\r\\n        align-items: flex-start;\\r\\n        gap: 10px;\\r\\n    }\\r\\n    .visit-btn {\\r\\n        width: 100%;\\r\\n        justify-content: center;\\r\\n    }\\r\\n}","js":""}', 0, 1, '2026-04-29 10:29:58', '2026-09-15 11:27:48', NULL),
	(29, 'मंत्रिमंडल सचिव', '/about-us/cabinet-secretary', NULL, NULL, NULL, NULL, NULL, '{"html":"<p><img src=\\"http://localhost:3000/images/our-team/a.jpg\\" alt=\\"प्रोफ़ाइल\\"></p><h2>डॉ. टी. वी. सोमानथन</h2><h3><strong>मंत्रिमंडल सचिव</strong></h3><p>डॉ. टी. वी. सोमनाथन भारतीय प्रशासनिक सेवा के1987 बैच के, तमिलनाडु कैडर के प्रतिष्ठित अधिकारी हैं, जो वर्तमान में <strong>30 अगस्त 2024</strong> से <strong>भारत के मंत्रिमंडल सचिव</strong> के रूप में कार्यरत हैं। तीन दशकों से अधिक के शानदार करियर के दौरान, वे राष्ट्रीय और अंतरराष्ट्रीय, दोनों स्तरों पर विभिन्न महत्वपूर्ण पदों पर कार्य कर चुके हैं।</p><p>मंत्रिमंडल सचिव के रूप में अपनी नियुक्ति से पहले, डॉ. सोमनाथन भारत के <strong>वित्त सचिव</strong> के रूप में कार्य करते हुए <strong>व्यय विभाग</strong> का नेतृत्व कर चुके हैं। केंद्र में उनकी पिछली भूमिकाओं में <strong>प्रधान मंत्री कार्यालय (PMO) में अपर सचिव</strong> और <strong>संयुक्त सचिव</strong> के रूप में कार्य किया जाना शामिल हैं, जहाँ उन्होंने विभिन्न अभिशासनात्मक और नीतिगत पहलों में महत्वपूर्ण भूमिका निभाई।</p><p>अंतरराष्ट्रीय स्तर पर, डॉ. सोमनाथन ने <strong>विश्व बैंक समूह</strong> में, शुरुआत में इसके प्रतिष्ठित <strong>यंग प्रोफेशनल्स प्रोग्राम </strong>के माध्यम से जुड़ने के उपरांत, वाशिंगटन, डीसी में <strong>कॉर्पोरेट मामलों के निदेशक</strong> के रूप में कार्य किया। सार्वजनिक वित्त और आर्थिक नीति के क्षेत्र में उनकी विशेषज्ञता को भारत और विदेश, दोनों में व्यापक मान्यता दी गई है।</p><p>कॉरपोरेट कार्य मंत्रालय में, उन्होंने <strong>संयुक्त सचिव</strong> के रूप में महत्वपूर्ण योगदान किया और सुधारों तथा विनियामक ढांचे पर ध्यान केंद्रित किया, जिससे कॉर्पोरेट प्रशासन को बढ़ावा मिला।</p><h3><strong>शैक्षणिक योग्यता</strong></h3><ul><li><strong>अर्थशास्त्र में पीएच.डी.</strong>, कलकत्ता विश्वविद्यालय</li><li><strong>कार्यपालक विकास कार्यक्रम</strong>, हार्वर्ड बिजनेस स्कूल</li><li><strong>चार्टर्ड अकाउंटेंट (सीए)</strong></li><li><strong>लागत लेखाकार (सीएमए)</strong></li><li><strong>कंपनी सचिव (सीएस)</strong></li></ul><p>डॉ. सोमनाथन गहन शैक्षणिक समझ और व्यावहारिक प्रशासनिक अनुभव रखते हैं, जो उन्हें भारत के सबसे प्रतिष्ठित सिविल सेवकों में से एक बनाता है। उनका पेशेवर सफ़र, उत्कृष्टता, ईमानदारी और राष्ट्र-निर्माण के प्रति उनकी प्रतिबद्धता को दर्शाता है।</p>","css":"body {\\r\\n  margin: 0;\\r\\n  font-family: Arial, sans-serif;\\r\\n}\\r\\n\\r\\n.container {\\r\\n  display: flex;\\r\\n  justify-content: center;\\r\\n  padding: 40px;\\r\\n}\\r\\n\\r\\n.profile-card {\\r\\n  display: flex;\\r\\n  gap: 40px;\\r\\n  padding: 30px;\\r\\n  max-width: 1100px;\\r\\n  width: 100%;\\r\\n}\\r\\n\\r\\n.profile-image img {\\r\\n  width: 280px;\\r\\n  height: auto;\\r\\n  object-fit: cover;\\r\\n}\\r\\n\\r\\n.profile-content {\\r\\n  flex: 1;\\r\\n}\\r\\n\\r\\n.profile-content h1 {\\r\\n  margin: 0;\\r\\n  font-size: 24px;\\r\\n  color: #1a2a5a;\\r\\n}\\r\\n\\r\\n.profile-content h3 {\\r\\n  margin-top: 5px;\\r\\n  font-size: 14px;\\r\\n  letter-spacing: 1px;\\r\\n}\\r\\n\\r\\n.profile-content p {\\r\\n  font-size: 14px;\\r\\n  line-height: 1.6;\\r\\n  color: #333;\\r\\n}\\r\\n\\r\\n.profile-content h4 {\\r\\n  margin-top: 20px;\\r\\n  font-size: 16px;\\r\\n}\\r\\n\\r\\n.profile-content ul {\\r\\n  padding-left: 20px;\\r\\n}\\r\\n\\r\\n.profile-content ul li {\\r\\n  margin-bottom: 8px;\\r\\n  font-size: 14px;\\r\\n}","js":""}', 0, 1, '2026-05-05 10:29:48', '2026-10-15 08:40:54', NULL),
