	(13136, 125, 'सचिवों की समिति (CoS) द्वारा विचार किए जाने वाले मामलों में अंतर-मंत्रालयी परामर्श प्रक्रिया।  मंत्रिमंडल/मंत्रिमंडल समितियों के निर्देश पर सीओएस द्वारा विचार किए जाने वाले मामलों में संबंधित सचिव द्वारा प्रभारी मंत्री का अनुमोदन अथवा अन्यथा के बारे में सूचित करने की आवश्यकता।', '/report_document/circular_inter_ministerial_consultations/Hindi/1_Upload_3344.pdf', 'application/pdf', '310.2 KB', 1, '2026-10-13 07:04:28', '2006-04-04 00:00:00'),
	(13137, 125, 'प्रक्रियागत आवश्यकताएं और त्रुटि रहित मंत्रिमंडल नोट तैयार करना।', '/report_document/circular_inter_ministerial_consultations/Hindi/1_Upload_3345.pdf', 'application/pdf', '1.1 MB', 1, '2026-10-13 07:04:28', '2005-03-31 00:00:00'),
	(13138, 125, 'मंत्रिमंडल नोटों में उन दिनांकों का उल्लेख करना,  जब परामर्श  किए गए मंत्रालयों/विभागों से टिप्पणियां प्राप्त हुईं।', '/report_document/circular_inter_ministerial_consultations/Hindi/1_Upload_3346.pdf', 'application/pdf', '445.7 KB', 1, '2026-10-13 07:04:28', '2004-12-01 00:00:00'),
	(13139, 126, 'कार्योत्तर अनुमोदन प्राप्त करने या सूचना के लिए मंत्रिमंडल/मंत्रिमंडल समिति हेतु नोट समय पर प्रस्तुत करने के संबंध में निर्देशों की पुनरावृत्ति।', '/report_document/circular_mou_rule12_ex_post_facto/Hindi/1_Upload_3347.pdf', 'application/pdf', '66.4 KB', 1, '2026-10-13 07:04:28', '2021-09-16 00:00:00'),
	(13140, 126, 'ई-समीक्षा पोर्टल के माध्यम से समझौता ज्ञापनों (एमओयू) की भी संरचित निगरानी।', '/report_document/circular_mou_rule12_ex_post_facto/Hindi/1_Upload_3350.pdf', 'application/pdf', '793.2 KB', 1, '2026-10-13 07:04:28', '2019-10-15 00:00:00'),
	(13141, 126, 'समझौता-ज्ञापन/अनुबंध (करार) पर हस्ताक्षर करने के उपरांत शीघ्र सूचना (एक माह के भीतर) के संबंध में दिनांक 21.03.2018 के निर्देशों की पुनरावृत्ति।', '/report_document/circular_mou_rule12_ex_post_facto/Hindi/1_Upload_3351.pdf', 'application/pdf', '502.1 KB', 1, '2026-10-13 07:04:28', '2018-06-01 00:00:00'),
	(13142, 126, 'कार्योत्तर अनुमोदन प्राप्त करने के लिए एक माह के भीतर मंत्रिमंडल/मंत्रिमंडल समिति हेतु नोट प्रस्तुत करने के संबंध में दिनांक 29.06.2011, 24.06.2015, 14.08.2015,  10.11.2016,  06.02.2017 और 08.09.2017 के निर्देशों की पुनरावृत्ति।', '/report_document/circular_mou_rule12_ex_post_facto/Hindi/1_Upload_3352.pdf', 'application/pdf', '482.9 KB', 1, '2026-10-13 07:04:28', '2018-03-21 00:00:00'),
	(13143, 126, 'मंत्रिमंडल/मंत्रिमंडल समितियों के सूचनार्थ नोट को एक माह की निर्धारित अवधि के भीतर रखने के संबंध में दिनांक 06.02.2017 के निर्देशों की पुनरावृत्ति।', '/report_document/circular_mou_rule12_ex_post_facto/Hindi/1_Upload_3353.pdf', 'application/pdf', '1.3 MB', 1, '2026-10-13 07:04:28', '2017-09-08 00:00:00'),
