	(13145, 126, 'कार्योत्तर अनुमोदन प्राप्त करने या सूचना के लिए नोट का एक महीने की निर्धारित अवधि के भीतर अग्रेषण।', '/report_document/circular_mou_rule12_ex_post_facto/Hindi/1_Upload_3355.pdf', 'application/pdf', '44.9 KB', 1, '2026-10-13 07:04:28', '2016-11-10 00:00:00'),
	(13146, 126, 'मंत्रालयों/विभागों द्वारा हस्ताक्षरित समझौता-ज्ञापनों को उन पर हस्ताक्षर करने के एक महीने के भीतर मंत्रिमंडल के समक्ष लाया जाना। इसमें विलम्ब होने पर विशिष्ट कारणों और औचित्य का भी उल्लेख करना।', '/report_document/circular_mou_rule12_ex_post_facto/Hindi/1_Upload_3356.pdf', 'application/pdf', '283.9 KB', 1, '2026-10-13 07:04:28', '2015-08-14 00:00:00'),
