	(1, 'डेस्कटॉप, प्रिंटर, स्कैनर, लैपटॉप और सर्वर आदि के वार्षिक रखरखाव अनुबंध के लिए निविदा में निमंत्रण', 'tender', NULL, '23', '2017-04-07', NULL, '/report_document/tender/hindi/1_Upload_1204.pdf', '5.6 MB', 2, '2026-06-08 07:17:33', '2026-08-03 12:04:53'),
	(2, 'कैबिनेट सचिवालय, राष्ट्रपति भवन में फर्नीचर वस्तुओं आदि की मरम्मत के लिए वार्षिक अनुबंध- निविदा आमंत्रित करने के लिए सूचना', 'tender', NULL, '23', '2018-02-01', NULL, '/report_document/tender/hindi/1_Upload_1374.pdf', '2.5 MB', 2, '2026-06-08 07:17:33', '2026-08-03 12:04:53'),
	(3, 'कैबिनेट सचिवालय, राष्ट्रपति भवन और इसके विंग में विद्युत उपकरणों की मरम्मत के लिए वार्षिक रखरखाव अनुबंध (एएमसी) - निविदा आमंत्रित करने की सूचना।', 'tender', NULL, '23', '2018-06-18', NULL, '/report_document/tender/hindi/1_Upload_1432.pdf', '420.1 KB', 2, '2026-06-08 07:17:33', '2026-08-03 12:04:53'),
	(4, 'मंत्रिमंडल सचिवालय में प्रोटोकॉल अधिकारी  (समूह "ख",अराजपत्रित, अननुसचिवीय, वेतन स्तर-7) के एक (01) पद को  प्रतिनियुक्ति/आमेलन के आधार पर भरे जाने के संबंध में।', 'vacancy', NULL, '74', '2023-04-24', NULL, '/report_document/vacancies/hindi/1_Upload_3596.pdf', '327.7 KB', 2, '2026-06-08 07:17:33', '2026-10-13 09:47:39'),
	(5, 'मंत्रिमंडल सचिवालय में वेतन मैट्रिक्स के लेवल 2 (रु. 19900-63200/-) में स्टाफ कार ड्राइवर ग्रेड (साधारण ग्रेड) में एक पद (1) भरा जाना', 'vacancy', NULL, '74', '2024-06-11', NULL, '/report_document/vacancies/hindi/1_Upload_3874.pdf', '381.8 KB', 2, '2026-06-08 07:17:33', '2026-10-13 09:47:37'),
