	(9, 'एनएसीडब्ल्यूसी में तकनीकी अधिकारी ', 'vacancy', 'राष्ट्रीय प्राधिकरण रासायनिक हथियार समझौता, मंत्रिमंडल सचिवालय में तकनीकी अधिकारी के पद को प्रतिनियुक्ति {अल्पकालिक संविदा सहित} पर भरना ', NULL, '2026-07-27', NULL, '/report_document/2.pdf', '3.2 MB', 1, '2026-10-13 09:49:40', '2026-10-13 09:59:08'),
	(10, 'मंत्रिमंडल सचिवालय में सहायक पुस्तकालय एवं सूचना अधिकारी के पद को भरा जाना ', 'vacancy', 'मंत्रिमंडल सचिवालय में सहायक पुस्तकालय और सूचना अधिकारी (समूह \'ख\', राजपत्रित, अलिपिकवर्गीय), वेतन स्तर – 7 के पद को प्रतिनियुक्ति आधार पर भरना ', NULL, '2026-07-03', NULL, '/report_document/3.pdf', '374.2 KB', 1, '2026-10-13 09:50:40', '2026-10-13 09:59:08');
